mapper.sql:
WHERE prescription.state = #{state}

    AND (

            prescription.id = #{keywordId}
            OR prescription.register_id = #{keywordId}
            OR prescription.drug_id = #{keywordId}
            OR

        drug.drug_code LIKE CONCAT('%', #{keyword}, '%')
        OR drug.drug_name LIKE CONCAT('%', #{keyword}, '%')
        OR drug.mnemonic_code LIKE CONCAT('%', #{keyword}, '%')
    )
